const std = @import("std"); const stor = @import("taskstore"); const time = @import("tasktime"); const armz = @import("taskarm"); const spaw = @import("spawn"); const regi = @import("registry"); const supe = @import("tasksuper"); const prob = @import("taskprobe"); const conf = @import("store"); const stre = @import("stream");
const tktickbase = @import("tk-tick-base.zig"); const ArmeReje = tktickbase.ArmeReje; const CF = tktickbase.CF; const CatcReqz = tktickbase.CatcReqz; const ChaiFini = tktickbase.ChaiFini; const ChaiRunz = tktickbase.ChaiRunz; const ChaiView = tktickbase.ChaiView; const Jobz = tktickbase.Jobz; const PollReqz = tktickbase.PollReqz; const RunzLast = tktickbase.RunzLast; const RunzLastReco = tktickbase.RunzLastReco; const RunzResu = tktickbase.RunzResu; const RunzSlot = tktickbase.RunzSlot; const StarReqz = tktickbase.StarReqz; const chaiResu = tktickbase.chaiResu; const finiPush = tktickbase.finiPush; const intoDupe = tktickbase.intoDupe; const jobzClon = tktickbase.jobzClon; const jobzFill = tktickbase.jobzFill; const logzDirz = tktickbase.logzDirz; const logzRota = tktickbase.logzRota; const membNext = tktickbase.membNext; const nowzMsec = tktickbase.nowzMsec; const plusPick = tktickbase.plusPick; const poolCoun = tktickbase.poolCoun; const poolPick = tktickbase.poolPick; const recoLast = tktickbase.recoLast; const ringDrop = tktickbase.ringDrop; const ringNote = tktickbase.ringNote; const ringSeal = tktickbase.ringSeal; const taskFind = tktickbase.taskFind;
const Sche = @import("tk-task-tick.zig").Sche;
pub fn logzRead(self: *Sche, allo: std.mem.Allocator, iozz: std.Io, iden: []const u8, maxz_byte: usize) ![]const u8 { _ = self; const dirz = try logzDirz(allo, iozz); const full = try std.fmt.allocPrint(allo, "{s}{c}{s}.log", .{ dirz, std.fs.path.sep, iden }); var file = std.Io.Dir.cwd().openFile(iozz, full, .{}) catch return error.NoLogYet; defer file.close(iozz); const leng = try file.length(iozz); const take: u64 = @min(leng, @as(u64, maxz_byte)); const from = leng - take; const buff = try allo.alloc(u8, @intCast(take)); const size = try file.readPositionalAll(iozz, buff, from); var outz = buff[0..size]; if (from > 0) { if (std.mem.indexOfScalar(u8, outz, '\n')) |nlin| outz = outz[nlin + 1 ..]; } return outz; }
pub fn runzLast(self: *Sche, allo: std.mem.Allocator, iozz: std.Io, iden: []const u8) ?RunzLast { if (self.last_runz_mute.lock(iozz)) |_| { const hitz = self.last_runz_cach.get(iden); self.last_runz_mute.unlock(iozz); if (hitz) |hit| return recoLast(allo, hit); } else |_| {} const foun = self.runzLastLogz(allo, iozz, iden); var reco: RunzLastReco = .{}; if (foun) |last| { reco.hasz = true; reco.code = last.code; reco.elap_msec = last.elap_msec; const leng = @min(last.when.len, reco.when.len); @memcpy(reco.when[0..leng], last.when[0..leng]); reco.when_leng = @intCast(leng); } self.cachPutz(iozz, iden, reco); return foun; }
pub fn cachPutz(self: *Sche, iozz: std.Io, iden: []const u8, reco: RunzLastReco) void { self.last_runz_mute.lock(iozz) catch return; defer self.last_runz_mute.unlock(iozz); if (self.last_runz_cach.getPtr(iden)) |pntr| { pntr.* = reco; return; } const keyz = self.gpaz.dupe(u8, iden) catch return; self.last_runz_cach.put(self.gpaz, keyz, reco) catch self.gpaz.free(keyz); }
pub fn runzNote(self: *Sche, iozz: std.Io, iden: []const u8, resu: RunzResu, nowz: time.Local) void { var reco: RunzLastReco = .{ .hasz = true, .code = resu.code, .elap_msec = resu.elap_msec }; const text = std.fmt.bufPrint(&reco.when, "{d:0>4}-{d:0>2}-{d:0>2} {d:0>2}:{d:0>2}:{d:0>2}", .{ nowz.year, nowz.month, nowz.day, nowz.hour, nowz.minute, nowz.second }) catch return; reco.when_leng = @intCast(text.len); self.cachPutz(iozz, iden, reco); }
pub fn runzLastPrim(self: *Sche, iozz: std.Io) void { const thre = std.Thread.spawn(.{}, primMain, .{ self, iozz }) catch return; thre.detach(); }
pub fn primMain(self: *Sche, iozz: std.Io) void { var aren = std.heap.ArenaAllocator.init(self.gpaz); defer aren.deinit(); const allo = aren.allocator(); var idsz: std.ArrayList([]const u8) = .empty; { self.mute.lock(iozz) catch return; defer self.mute.unlock(iozz); const load = self.load orelse return; for (load.task) |task| idsz.append(allo, allo.dupe(u8, task.id) catch continue) catch {}; } for (idsz.items) |iden| { if (self.stop.load(.acquire)) return; _ = self.runzLast(allo, iozz, iden); } }
pub fn catcScan(self: *Sche, iozz: std.Io) void { var pool: [32]CatcReqz = undefined; var coun: usize = 0; { self.mute.lock(iozz) catch return; defer self.mute.unlock(iozz); const load = self.load orelse return; for (load.task) |task| { if (!task.on or coun >= pool.len) continue; const catc = task.catchup orelse continue; if (!std.mem.eql(u8, catc, "once")) continue; const iszz_cron = std.mem.eql(u8, task.type, "cron"); const iszz_once = std.mem.eql(u8, task.type, "once"); const iszz_chai = std.mem.eql(u8, task.type, "chai"); if (!iszz_cron and !iszz_once and !iszz_chai) continue; const reqz = &pool[coun]; reqz.* = .{ .iszz_once = iszz_once, .iszz_chai = iszz_chai }; reqz.iden = intoDupe(&reqz.iden_buff, task.id); reqz.sche = intoDupe(&reqz.sche_buff, task.sche orelse ""); coun += 1; } } if (coun == 0) return; var aren = std.heap.ArenaAllocator.init(self.gpaz); defer aren.deinit(); const allo = aren.allocator(); const nowz = time.localNow(); var miss: [32]bool = @splat(false); for (pool[0..coun], 0..) |*reqz, indx| { if (reqz.iszz_once) { const targ = time.parseOnce(reqz.sche) catch continue; if (nowz.minute_stamp - targ <= time.ONCE_LATE_WINDOW_MIN) continue; if (std.mem.eql(u8, stor.onceStamRead(allo, iozz, reqz.iden), reqz.sche)) continue; miss[indx] = true; } else { const fiel = time.parseCron(reqz.sche) catch continue; const last = stor.fireLastRead(allo, iozz, reqz.iden) orelse continue; var minu = @max(last + 1, nowz.minute_stamp - CF.catc_maxz_minu); while (minu < nowz.minute_stamp) : (minu += 1) { if (time.cronMatch(fiel, time.localFromMinuteStamp(minu))) { miss[indx] = true; break; } } } } var duez_buff: [32]Jobz = undefined; var duez_coun: usize = 0; const nowz_msec = nowzMsec(iozz); { self.mute.lock(iozz) catch return; defer self.mute.unlock(iozz); const load = self.load orelse return; for (pool[0..coun], 0..) |*reqz, indx| { if (!miss[indx]) continue; if (reqz.iszz_chai) { for (self.arme) |*arme| if (std.mem.eql(u8, arme.id, reqz.iden) and arme.isChain()) { _ = arme.requestHand(); }; continue; } const task = taskFind(load.task, reqz.iden) orelse continue; const jobz = &duez_buff[duez_coun]; jobzFill(jobz, reqz.iden, task); jobz.iszz_catc = true; jobz.notz_befo_msec = nowz_msec + @as(i64, @intCast(duez_coun)) * CF.catc_stag_msec; if (reqz.iszz_once) jobz.once_stam = intoDupe(&jobz.once_buff, task.sche orelse ""); duez_coun += 1; } } if (duez_coun > 0) { _ = self.fire_coun.fetchAdd(@intCast(duez_coun), .monotonic); self.disp(iozz, duez_buff[0..duez_coun]); } }
pub fn runzLastLogz(self: *Sche, allo: std.mem.Allocator, iozz: std.Io, iden: []const u8) ?RunzLast { const tail = self.logzRead(allo, iozz, iden, 4096) catch return null; const trim = std.mem.trimEnd(u8, tail, "\r\n \t"); if (trim.len == 0) return null; const line = if (std.mem.lastIndexOfScalar(u8, trim, '\n')) |nlin| trim[nlin + 1 ..] else trim; const exit_indx = std.mem.indexOf(u8, line, "exit:") orelse return null; var rest = line[exit_indx + "exit:".len ..]; const code_endz = std.mem.indexOfScalar(u8, rest, ' ') orelse rest.len; const code = std.fmt.parseInt(i32, rest[0..code_endz], 10) catch return null; var msec: i64 = 0; rest = rest[code_endz..]; if (std.mem.indexOf(u8, rest, "ms")) |msin| { const head = std.mem.trimEnd(u8, rest[0..msin], " \t"); const numz = (std.mem.lastIndexOfScalar(u8, head, ' ') orelse 0); msec = std.fmt.parseInt(i64, std.mem.trim(u8, head[numz..], " \t"), 10) catch 0; } const when = if (line.len >= 19) line[0..19] else ""; return .{ .code = code, .elap_msec = msec, .when = when }; }
pub fn fireCoun(self: *Sche, iden: []const u8) ?struct { coun: u32, last_msec: i64, kind: []const u8 } { for (self.arme) |*arme| { if (std.mem.eql(u8, arme.id, iden)) { return .{ .coun = arme.fire_count, .last_msec = arme.last_fire_ms, .kind = arme.typeName() }; } } return null; }
pub fn fireNext(self: *Sche, iden: []const u8, nowz: time.Local) ?i64 { for (self.arme) |*arme| { if (std.mem.eql(u8, arme.id, iden)) return arme.nextFireStamp(nowz); } return null; }
